    'ε':'ἐ','Ε':'Ἐ',
    'η':'ἠ','Η':'Ἠ',
    'ο':'ὀ','Ο':'Ὀ',
    'ω':'ὠ','Ω':'Ὠ',
    'ι':'ἰ','Ι':'Ἰ',
    'υ':'ὐ','Υ':'Ὑ'
